type subp_entity = Gnat_loc.loc

type id = int
type check =
  { id             : id;
    check_kind     : check_kind;
    sloc           : Gnat_loc.loc;
    shape          : string;
    already_proved : bool
  }

type extra_info =
  { pretty_node : int option;
    inlined     : int option;
  }

type vc_info =
  { check      : check;
    extra_info : extra_info;
  }

let colon = ':'

let colon_split s =
   let acc : string list ref = ref [] in
   let last_index = ref (String.length s) in
   let cur_index = ref (String.length s - 1) in
   try
      while true do
         cur_index := String.rindex_from s (!cur_index - 1) colon;
         acc :=
            String.sub s (!cur_index + 1) (!last_index - !cur_index - 1):: !acc;
         last_index := !cur_index;
      done;
      !acc
   with Invalid_argument _ | Not_found ->
      String.sub s 0 (!last_index) :: !acc

(* This is to be executed when scheduling ends *)
let ending c () =
  Debug.Stats.record_timing "gnatwhy3.run_vcs"
    (fun () -> C.remove_all_valid_ce_attempt c.Controller_itp.controller_session);
  Debug.Stats.record_timing "gnatwhy3.save_session" (fun () -> C.save_session c);
  Gnat_checks.iter (report_messages c);
  let s = Buffer.contents escape_buffer in
  if s <> "" then
    Gnat_report.add_warning s;
  Gnat_report.print_messages ();
  (* Dump profiling data (when compiled with profiling enabled) to file whose
     name is based on the processed .mlw file; otherwise profile data from
     several compilation would be written to a single gmon.out file and
     overwrite each other. When compiled with profiling disabled it has no
     visible effect. Note: we set the filename just before the program exit
     to not interfere with profiling of provers.
   *)
  let basename =
    Filename.chop_extension
      (Filename.basename Gnat_config.filename) in
  Unix.putenv "GMON_OUT_PREFIX" (basename ^ "_gnatwhy3_gmon.out")

let normal_handle_one_subp c subp =
   C.init_subp_vcs c subp;
   let s = c.Controller_itp.controller_session in
   Gnat_checks.iter_leaf_goals s subp (register_goal c)

(* save session on interrupt initiated by the user *)
let save_session_and_exit c signum =
  (* Ignore all SIGINT, SIGHUP and SIGTERM, which may be received when
     gnatprove is called in GNATStudio, so that the session file is always
     saved. Wrap in exception block as some signals are not supported on
     windows. *)
  begin try
    Sys.set_signal Sys.sigint Sys.Signal_ignore;
    Sys.set_signal Sys.sighup Sys.Signal_ignore;
    Sys.set_signal Sys.sigterm Sys.Signal_ignore;
  with Invalid_argument _ -> () end;
  C.save_session c;
  exit signum

(* The state of the module consists of these mutable structures *)
let explmap : check_rec Gnat_expl.HCheck.t = Gnat_expl.HCheck.create 17
(* maps proof checks to goals *)

let goalmap : Gnat_expl.vc_info GoalMap.t = GoalMap.create 17
(* maps goals to their checks *)

let total_nb_goals : int ref = ref 0
let nb_checks : int ref = ref 0

let not_interesting : GoalSet.t = GoalSet.empty ()

let clear () =
   Gnat_expl.HCheck.clear explmap;
   GoalMap.clear goalmap;
   GoalSet.reset not_interesting;
   total_nb_goals := 0;
   nb_checks := 0

let find e =
   try Gnat_expl.HCheck.find explmap e
   with Not_found ->
      let r = empty_check () in
      Gnat_expl.HCheck.add explmap e r;
      incr nb_checks;
      r

let add_to_check ~toplevel ex go =
  let check = ex.Gnat_expl.check in
  (* add a goal to a check.
   * A goal can be "top-level", that is a direct goal coming from WP, or not
   * top-level, that is obtained by transformation. *)
   let filter_line = Gnat_config.limit_lines = [] || List.exists (function
      | Gnat_expl.Limit_Line l ->
         Gnat_loc.equal_line l (Gnat_expl.get_loc check)
      | Gnat_expl.Limit_Check c ->
         (c.Gnat_expl.check_kind = Gnat_expl.get_check_kind check)
         && (Gnat_loc.equal_loc c.Gnat_expl.sloc (Gnat_expl.get_loc check))
   ) Gnat_config.limit_lines
   in
   let filter_region =
      match Gnat_config.limit_region with
      | Some r ->
         Gnat_loc.in_region r (Gnat_expl.get_loc check)
      | None -> true
   in
   if filter_line && filter_region then begin
      incr total_nb_goals;
      GoalMap.add goalmap go ex;
      let cr = find check in
      GoalSet.add cr.to_be_scheduled go;
      GoalSet.add cr.to_be_proved go;
      if toplevel then GoalSet.add cr.toplevel go;
   end

let get_vc_info goal = GoalMap.find goalmap goal
let get_check_of_goal goal = (get_vc_info goal).Gnat_expl.check
let get_extra_info goal = (get_vc_info goal).Gnat_expl.extra_info

let add_clone derive goal =
   let check = get_vc_info derive in
   add_to_check ~toplevel:false check goal

let limit ~prover ~warning =
  let config_prover = get_prover_config config prover in
  let prover_name = prover.prover_name in
  { Call_provers.limit_mem = limit_mem ();
    Call_provers.limit_time = limit_time ~prover:prover_name ~warning;
    limit_steps = steps ~config_prover}

(* hash-consing constructors for terms *)

let mk_term n ty = {
  t_node  = n;
  t_attrs = Sattr.empty;
  t_loc   = None;
  t_ty    = ty;
}

let t_var v         = mk_term (Tvar v) (Some v.vs_ty)
let t_const c ty    = mk_term (Tconst c) (Some ty)
let t_app f tl ty   = mk_term (Tapp (f, tl)) ty
let t_if f t1 t2    = mk_term (Tif (f, t1, t2)) t2.t_ty
let t_let t1 bt ty  = mk_term (Tlet (t1, bt)) ty
let t_case t1 bl ty = mk_term (Tcase (t1, bl)) ty
let t_eps bf ty     = mk_term (Teps bf) ty
let t_quant q qf    = mk_term (Tquant (q, qf)) None
let t_binary op f g = mk_term (Tbinop (op, f, g)) None
let t_not f         = mk_term (Tnot f) None
let t_true          = mk_term (Ttrue) None
let t_false         = mk_term (Tfalse) None

let t_attr_set ?loc l t = { t with t_attrs = l; t_loc = loc }

let t_attr_add l t = { t with t_attrs = Sattr.add l t.t_attrs }

let t_attr_remove l t = { t with t_attrs = Sattr.remove l t.t_attrs }

let t_attr_copy s t =
  if s == t then s else
  if t_similar s t && Sattr.is_empty t.t_attrs && t.t_loc = None then s else
  let attrs = Sattr.union s.t_attrs t.t_attrs in
  let loc = if t.t_loc = None then s.t_loc else t.t_loc in
  { t with t_attrs = attrs; t_loc = loc }

let fresh_vsymbol v =
  create_vsymbol (id_clone v.vs_name) v.vs_ty

let vs_rename h v =
  let u = fresh_vsymbol v in
  Mvs.add v (t_var u) h, u

let vl_rename h vl =
  Lists.map_fold_left vs_rename h vl

let pat_rename h p =
  let add_vs v () = fresh_vsymbol v in
  let m = Mvs.mapi add_vs p.pat_vars in
  let p = pat_rename_all m p in
  Mvs.union (fun _ _ t -> Some t) h (Mvs.map t_var m), p

let t_open_bound (v,b,t) =
  let m,v = vs_rename b.bv_subst v in
  v, t_subst_unsafe m t

let t_open_bound_with e (v,b,t) =
  vs_check v e;
  let m = Mvs.add v e b.bv_subst in
  t_subst_unsafe m t

let t_open_branch (p,b,t) =
  let m,p = pat_rename b.bv_subst p in
  p, t_subst_unsafe m t

let t_open_quant (vl,b,tl,f) =
  let m,vl = vl_rename b.bv_subst vl in
  let tl = tr_map (t_subst_unsafe m) tl in
  vl, tl, t_subst_unsafe m f
